using System.Text.Json;using System.Windows;using OncaPDV.Infrastructure;namespace OncaPDV.Desktop;public partial class DiagnosticWindow:Window{private readonly DiagnosticService _service;public DiagnosticWindow(DiagnosticService service){_service=service;InitializeComponent();Loaded+=Load;}private async void Load(object sender,RoutedEventArgs e)=>Output.Text=JsonSerializer.Serialize(await _service.ReadAsync(),new JsonSerializerOptions{WriteIndented=true});private async void Export_Click(object sender,RoutedEventArgs e)=>MessageBox.Show($"Diagnóstico exportado em:\n{await _service.ExportAsync()}");}
